pub fn insert_question(conn: &mut Connection, quiz_id: i64, body: &str, active: bool, options: &[(String, bool)]) -> rusqlite::Result<i64> {
    let tx = conn.transaction()?;
    let position: i64 = tx.query_row(...)?;
    tx.execute("INSERT INTO questions (quiz_id, body, is_active, position) VALUES (?1,?2,?3,?4)", params![...])?;
    let qid = tx.last_insert_rowid();
    for (i,(text,correct)) in options.iter().enumerate() {
        tx.execute("INSERT INTO options (question_id, body, is_correct, position) VALUES (?1,?2,?3,?4)", params![qid, text, *correct as i32, i as i64])?;
    }
    tx.commit()?;
    Ok(qid)
}
