pub fn move_question(conn: &mut Connection, quiz_id: i64, qid: i64, up: bool) -> rusqlite::Result<()> {
    let ids: Vec<i64> = {
        let mut stmt = conn.prepare("SELECT id FROM questions WHERE quiz_id=?1 ORDER BY position, id")?;
        stmt.query_map(params![quiz_id], |r| r.get(0))?.collect::<Result<_,_>>()?
    };
    let Some(pos) = ids.iter().position(|x| *x == qid) else { return Ok(()); };
    let other = if up { pos.checked_sub(1) } else { if pos+1 < ids.len() { Some(pos+1) } else { None } };
    if let Some(opos) = other {
        let tx = conn.transaction()?;
        // simpler: set positions
        tx.execute("UPDATE questions SET position=?1 WHERE id=?2", params![opos as i64, ids[pos]])?;
        tx.execute("UPDATE questions SET position=?1 WHERE id=?2", params![pos as i64, ids[opos]])?;
        tx.commit()?;
    }
    Ok(())
}
```
