Auth check:
```rust
fn authorized(req: &Request, app: &App) -> bool {
    let Some(h) = req.headers().iter().find(|h| h.field.equiv("Authorization")) else { return false; };
    let val = h.value.as_str();
    let Some(b64) = val.strip_prefix("Basic ").or_else(|| val.strip_prefix("basic ")) else { return false; };
    use base64::Engine;
    let Ok(bytes) = base64::engine::general_purpose::STANDARD.decode(b64.trim()) else { return false; };
    let Ok(text) = String::from_utf8(bytes) else { return false; };
    let Some((u,p)) = text.split_once(':') else { return false; };
    u == app.username && p == app.password
}
```
