pub fn list_questions(conn: &Connection, quiz_id: i64, only_active: bool) -> rusqlite::Result<Vec<Question>> {
    let sql = if only_active {
        "SELECT id, body, is_active FROM questions WHERE quiz_id = ?1 AND is_active = 1 ORDER BY position, id"
    } else {
        "SELECT id, body, is_active FROM questions WHERE quiz_id = ?1 ORDER BY position, id"
    };
    let mut stmt = conn.prepare(sql)?;
    let qs: Vec<(i64,String,bool)> = stmt
        .query_map(params![quiz_id], |r| Ok((r.get::<_, i64>(0)?, r.get::<_, String>(1)?, r.get::<_, i64>(2)? != 0)))?
        .collect::<rusqlite::Result<Vec<_>>>()?;
    let mut out = Vec::with_capacity(qs.len());
    for (id, text, active) in qs {
        let options = load_options(conn, id)?;
        out.push(Question{id,text,active,options});
    }
    Ok(out)
}

fn load_options(conn: &Connection, question_id: i64) -> rusqlite::Result<Vec<OptionItem>> {
    let mut stmt = conn.prepare("SELECT id, body, is_correct FROM options WHERE question_id = ?1 ORDER BY position, id")?;
    let rows = stmt.query_map(params![question_id], |r| Ok(OptionItem{
        id: r.get(0)?,
        text: r.get(1)?,
        is_correct: r.get::<_, i64>(2)? != 0,
    }))?;
    rows.collect()
}
```

