```rust
fn dispatch(req: &mut Request, app: &Arc<App>) -> Reply {
    let raw_path = req.url().split('?').next().unwrap_or("/").to_string();
    let method = req.method().as_str().to_string();
    if (raw_path == "/moderate" || raw_path.starts_with("/moderate/")) && !auth_ok(req, app) {
        return Reply::unauthorized();
    }
    let segments: Vec<&str> = raw_path.split('/').filter(|s| !s.is_empty()).collect();
    let mut params: HashMap<String,String> = HashMap::new();
    if method == "POST" {
        let mut body = String::new();
        if req.as_reader().read_to_string(&mut body).is_ok() {
            params = serde_urlencoded::from_str(&body).unwrap_or_default();
        }
    }
    let seg: Vec<String> = segments.iter().map(|s| s.to_string()).collect();
    match (method.as_str(), seg.as_slice()) {
        ("GET", ["up"]) => Reply::plain(200, "OK"),
        ("GET", []) => Reply::redirect("/moderate"),
        ("GET", ["static","quizzy.css"]) => Reply::css(CSS),
        ("GET", ["static","Inter-latin.woff2"]) => Reply::font(FONT),
        ("GET", ["moderate"]) => handlers::index(app),
        ("GET", ["moderate","quizzes","new"]) => handlers::quiz_new(app),
        ("POST", ["moderate","quizzes"]) => handlers::quiz_create(app, &params),
        ("GET", ["moderate","quizzes", id]) => with_id(id, |id| handlers::quiz_show(app,id)),
        ...
    }
