fn auth_ok(request: &Request, app: &App) -> bool {
    let Some(header) = request.headers().iter().find(|h| h.field.equiv("Authorization")) else { return false; };
    let value = header.value.as_str();
    let Some(prefix) = value.get(..6) else { return false; };
    if !prefix.eq_ignore_ascii_case("basic ") { return false; }
    let encoded = value[6..].trim();
    let Ok(bytes) = base64::engine::general_purpose::STANDARD.decode(encoded) else { return false; };
    let Ok(text) = String::from_utf8(bytes) else { return false; };
    let Some((username, password)) = text.split_once(':') else { return false; };
    username == app.username && password == app.password
}
