"""Minimal Chrome DevTools Protocol client over --remote-debugging-pipe."""
import json, os, select, subprocess, time

class CDPError(Exception):
    pass

class Browser:
    def __init__(self, chromium="/usr/bin/chromium"):
        r_cmd, w_cmd = os.pipe()    # parent writes -> child fd3
        r_out, w_out = os.pipe()    # child fd4 -> parent reads
        def preexec():
            os.dup2(r_cmd, 3)
            os.dup2(w_out, 4)
        self.proc = subprocess.Popen(
            [chromium, "--headless=new", "--no-sandbox", "--disable-gpu",
             "--disable-dev-shm-usage", "--no-first-run", "--no-default-browser-check",
             "--remote-debugging-pipe", "about:blank"],
            close_fds=False, preexec_fn=preexec,
            stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        os.close(r_cmd); os.close(w_out)
        self.w = os.fdopen(w_cmd, "wb", buffering=0)
        self.r = os.fdopen(r_out, "rb", buffering=0)
        self.buf = b""
        self.next_id = 1
        self.responses = {}
        self.events = []
        self.load_count = 0
        self.dialogs = []
        self.console = []
        self.exceptions = []
        self.auth_count = 0
        self.auto_accept_dialogs = True
        self.session = None

    # ------------------------------------------------------------- plumbing
    def _write(self, msg):
        self.w.write(json.dumps(msg).encode() + b"\0")

    def _cmd(self, method, params=None, session=None):
        mid = self.next_id; self.next_id += 1
        msg = {"id": mid, "method": method}
        if params is not None:
            msg["params"] = params
        if session:
            msg["sessionId"] = session
        self._write(msg)
        return mid

    def _read_one(self, timeout):
        if b"\0" in self.buf:
            raw, self.buf = self.buf.split(b"\0", 1)
            if raw.strip():
                return json.loads(raw)
            return None
        ready, _, _ = select.select([self.r], [], [], max(0.0, timeout))
        if not ready:
            return None
        chunk = self.r.read(65536)
        if not chunk:
            raise CDPError("chromium pipe closed")
        self.buf += chunk
        return None

    def _handle_event(self, msg):
        method = msg.get("method")
        params = msg.get("params", {})
        session = msg.get("sessionId")
        if method == "Page.loadEventFired":
            self.load_count += 1
        elif method == "Page.javascriptDialogOpening":
            self.dialogs.append((params.get("type"), params.get("message")))
            if self.auto_accept_dialogs:
                self._cmd("Page.handleJavaScriptDialog", {"accept": True}, session)
        elif method == "Fetch.authRequired":
            self.auth_count += 1
            self._cmd("Fetch.continueWithAuth", {
                "requestId": params["requestId"],
                "authChallengeResponse": {"response": "ProvideCredentials",
                                          "username": "mod", "password": "secret"}}, session)
        elif method == "Runtime.consoleAPICalled":
            self.console.append(params)
        elif method == "Runtime.exceptionThrown":
            self.exceptions.append(params)
        else:
            self.events.append(msg)

    def wait_for(self, predicate, timeout=15):
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            if predicate():
                return True
            msg = self._read_one(deadline - time.monotonic())
            if msg is None:
                continue
            if "id" in msg:
                self.responses.setdefault(msg["id"], msg)
            elif method := msg.get("method"):
                self._handle_event(msg)
        return predicate()

    def send(self, method, params=None, session=None, timeout=15):
        mid = self._cmd(method, params, session)
        ok = self.wait_for(lambda: mid in self.responses, timeout)
        if not ok:
            raise CDPError(f"timeout waiting for {method}")
        msg = self.responses.pop(mid)
        if "error" in msg:
            raise CDPError(f"{method}: {msg['error']}")
        return msg.get("result", {})

    # ------------------------------------------------------------- lifecycle
    def start(self):
        res = None
        deadline = time.monotonic() + 15
        while time.monotonic() < deadline:
            try:
                res = self.send("Target.getTargets", timeout=2)
                break
            except CDPError:
                time.sleep(0.2)
        if res is None:
            raise CDPError("browser did not start")
        targets = [t for t in res["targetInfos"] if t["type"] == "page"]
        if not targets:
            created = self.send("Target.createTarget", {"url": "about:blank"})
            target_id = created["targetId"]
        else:
            target_id = targets[0]["targetId"]
        attached = self.send("Target.attachToTarget", {"targetId": target_id, "flatten": True})
        self.session = attached["sessionId"]
        self.send("Page.enable", {}, self.session)
        self.send("Runtime.enable", {}, self.session)
        self.send("Fetch.enable", {"handleAuthRequests": True}, self.session)

    def navigate(self, url):
        before = self.load_count
        self.send("Page.navigate", {"url": url}, self.session)
        if not self.wait_for(lambda: self.load_count > before, 20):
            raise CDPError(f"navigation did not finish: {url}")

    def eval(self, expression):
        res = self.send("Runtime.evaluate",
                        {"expression": expression, "returnByValue": True},
                        self.session)
        if "exceptionDetails" in res:
            raise CDPError(f"js error: {res['exceptionDetails']}")
        return res["result"].get("value")

    def html(self):
        return self.eval("document.documentElement.outerHTML")

    def url(self):
        return self.eval("location.href")

    def close(self):
        try:
            self.w.close()
        except Exception:
            pass
        try:
            self.proc.terminate()
            self.proc.wait(timeout=5)
        except Exception:
            try: self.proc.kill()
            except Exception: pass
